mapper.select:
SELECT `code`, `name`, `market`, `exchange`, `board`, `industry` FROM `stock_info`
WHERE `code` LIKE CONCAT('%', #{keyword}, '%') OR `name` LIKE CONCAT('%', #{keyword}, '%') OR `secid` LIKE CONCAT('%', #{keyword}, '%')
ORDER BY CASE WHEN `code` LIKE CONCAT(#{keyword}, '%') THEN 0 ELSE 1 END, `code` LIMIT #{limit}

SELECT FROM `stock_info` WHERE `secid` IS NOT NULL AND `secid` <> '' AND (
`code` LIKE CONCAT(#{prefix}, '%')
) ORDER BY `code` LIMIT #{limit}
